    const studentResults = results.filter(r => r.student_id === selectedStudentId);
    const studentName = getStudentFullName(selectedStudentId);
    if (studentResults.length === 0) { setSummaryError("No results found for this student."); setIsSummaryLoading(false); return; }
    const resultsText = studentResults.map(r => `- ${getSubjectName(r.subject_id)} in ${getExamName(r.exam_id)}: ${r.marks_obtained}/${r.total_marks}`).join('\n');
    const systemPrompt = "Act as a helpful and encouraging school teacher in India. Your tone should be positive and constructive.";
    const userQuery = `Write a concise, one-paragraph performance summary for ${studentName} for their parents. Based on these results, highlight one strength and suggest one area for improvement.\n\nResults:\n${resultsText}`;
    const payload = { contents: [{ parts: [{ text: userQuery }] }], systemInstruction: { parts: [{ text: systemPrompt }] }, };
    try { const summary = await callGeminiAPI(payload); setPerformanceSummary(summary); }
    catch (error) { setSummaryError("AI summary could not be generated."); }
    finally { setIsSummaryLoading(false); }
  };

  const handleGenerateQuiz = async () => {
      if (!quizTopic.trim()) { setQuizError("Please enter a topic."); return; }
      setIsQuizLoading(true); setGeneratedQuiz([]); setQuizError(''); setUserAnswers({}); setShowQuizResults(false);
      const userQuery = `Generate a 5-question multiple-choice quiz on "${quizTopic}". Provide 4 options per question, one correct.`;
      const quizSchema = { type: "ARRAY", items: { type: "OBJECT", properties: { question: { type: "STRING" }, options: { type: "ARRAY", items: { type: "STRING" }}, correct_answer: { type: "STRING" } }, required: ["question", "options", "correct_answer"] } };
      const payload = { contents: [{ parts: [{ text: userQuery }] }], generationConfig: { responseMimeType: "application/json", responseSchema: quizSchema } };
      try { const responseText = await callGeminiAPI(payload); const quizData = JSON.parse(responseText); setGeneratedQuiz(quizData); }
      catch (error) { setQuizError("Quiz could not be generated. Try another topic."); }
      finally { setIsQuizLoading(false); }
  };

  const handleExplainQuiz = async () => {
