    const schema = { type: 'ARRAY', items: { type: 'OBJECT', properties: { question: { type: 'STRING' }, user_answer: { type: 'STRING' }, correct_answer: { type: 'STRING' }, correct: { type: 'BOOLEAN' }, explanation: { type: 'STRING' } }, required: ['question','user_answer','correct_answer','correct','explanation'] } };
    try {
      const text = await callGeminiAPI({ contents: [{ parts: [{ text: explanationPrompt }] }], generationConfig: { responseMimeType: 'application/json', responseSchema: schema } });
      setQuizExplanations(JSON.parse(text));
    } catch (e) {
      setQuizExplanations(generatedQuiz.map((q, i) => ({ question: q.question, user_answer: userAnswers[i] || '', correct_answer: q.correct_answer, correct: (userAnswers[i] === q.correct_answer), explanation: 'Review the concept and compare each option logically.' })));
