                          <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Check-in</th>
                          <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Remarks</th>
                          <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
                        </tr>
                      </thead>
                      <tbody className="bg-white divide-y divide-gray-200">
                        {getFilteredAttendance().slice(0, 50).map(record => (
                          <tr key={record.attendance_id} className="hover:bg-gray-50">
                            <td className="px-6 py-4 whitespace-nowrap">
                              <input
                                type="checkbox"
                                checked={selectedAttendance.includes(record.attendance_id)}
                                onChange={() => handleAttendanceToggle(record.attendance_id)}
                                className="rounded border-gray-300 text-emerald-600 focus:ring-emerald-500"
                              />
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap">
                              <div className="flex items-center">
                                <div className="h-8 w-8 rounded-full bg-emerald-100 flex items-center justify-center mr-3">
                                  <span className="text-xs font-medium text-emerald-700">
                                    {(() => {
                                      const student = students.find(s => s.student_id === record.student_id);
                                      return student ? `${student.first_name[0]}${student.last_name[0]}` : '??';
                                    })()}
                                  </span>
                                </div>
                                <div>
                                  <div className="text-sm font-medium text-gray-900">{getStudentFullName(record.student_id)}</div>
                                  <div className="text-sm text-gray-500">ID: {record.student_id}</div>
                                </div>
                              </div>
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{getClassName(record.class_id)}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{record.subject}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{record.time_slot}</td>
                            <td className="px-6 py-4 whitespace-nowrap">
                              <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                                record.status === 'Present' ? 'bg-green-100 text-green-800' :
                                record.status === 'Late' ? 'bg-yellow-100 text-yellow-800' :
                                'bg-red-100 text-red-800'
                              }`}>
                                {record.status}
                              </span>
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                              {record.check_in_time || '-'}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                              {record.remarks || '-'}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                              <button className="text-emerald-600 hover:text-emerald-900 mr-3">Edit</button>
                              <button className="text-red-600 hover:text-red-900">Delete</button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {attendanceView === 'analytics' && (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  <div className="bg-white rounded-lg shadow p-6">
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">Weekly Attendance Trends</h3>
                    <div className="space-y-4">
                      {['2025-09-16', '2025-09-17', '2025-09-18', '2025-09-19', '2025-09-20', '2025-09-21'].map(date => {
                        const dayStats = getAttendanceStats(null, date);
                        return (
                          <div key={date} className="flex items-center justify-between">
                            <span className="text-sm font-medium text-gray-700">{new Date(date).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}</span>
                            <div className="flex items-center space-x-2">
                              <div className="w-32 bg-gray-200 rounded-full h-2">
                                <div 
                                  className="bg-emerald-600 h-2 rounded-full" 
                                  style={{width: `${dayStats.presentRate}%`}}
                                ></div>
                              </div>
                              <span className="text-sm font-medium text-gray-900 w-12">{dayStats.presentRate}%</span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                  
                  <div className="bg-white rounded-lg shadow p-6">
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">Top Performers</h3>
                    <div className="space-y-3">
                      {students.slice(0, 10).map((student, index) => {
                        const studentAttendance = attendanceData.filter(a => a.student_id === student.student_id);
                        const presentCount = studentAttendance.filter(a => a.status === 'Present' || a.status === 'Late').length;
                        const attendanceRate = studentAttendance.length > 0 ? (presentCount / studentAttendance.length * 100).toFixed(1) : 0;
                        
                        return (
                          <div key={student.student_id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                            <div className="flex items-center">
                              <span className="text-lg font-bold text-emerald-600 mr-3">#{index + 1}</span>
                              <div>
                                <div className="text-sm font-medium text-gray-900">{student.first_name} {student.last_name}</div>
                                <div className="text-xs text-gray-500">{getClassName(student.class_id)}</div>
                              </div>
                            </div>
                            <div className="text-right">
                              <div className="text-sm font-bold text-emerald-600">{attendanceRate}%</div>
                              <div className="text-xs text-gray-500">{presentCount}/{studentAttendance.length}</div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Add other tab contents here */}
          {currentTab === 'results' && (
            <div className="space-y-6">
              <h2 className="text-3xl font-bold text-gray-900">Student Results</h2>
              <div className="bg-white shadow overflow-hidden sm:rounded-lg">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Student
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Exam
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Subject
                      </th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Marks
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {results.slice(0, 20).map(result => (
                      <tr key={result.result_id}>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                          {getStudentFullName(result.student_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {getExamName(result.exam_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {getSubjectName(result.subject_id)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                          {result.marks_obtained}/{result.total_marks}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default JharkhandAcademicSystem;
